def trim_history(messages, budget):
    # Validate budget is nonnegative
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate every message cost is nonnegative
    for msg in messages:
        if msg['cost'] < 0:
            raise ValueError("all message costs must be nonnegative")

    # Compute total cost of all messages
    total = sum(msg['cost'] for msg in messages)

    # Trim from the beginning until the suffix sum fits the budget
    i = 0
    while i < len(messages) and total > budget:
        total -= messages[i]['cost']
        i += 1

    # Return a new list (no mutation of input)
    return list(messages[i:])

