def summarize_usage(events):
    request_max = {}

    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        if input_count < 0 or output_count < 0:
            raise ValueError("Negative count not allowed")

        if request_id not in request_max:
            request_max[request_id] = {'input': 0, 'output': 0}

        request_max[request_id]['input'] = max(request_max[request_id]['input'], input_count)
        request_max[request_id]['output'] = max(request_max[request_id]['output'], output_count)

    total_input = 0
    total_output = 0
    for rid in request_max:
        total_input += request_max[rid]['input']
        total_output += request_max[rid]['output']

    return {'input': total_input, 'output': total_output}

